ui-v146.css:
/* Ver.146: quick status, recent ToDo history, and transient silent-save styling. */

.detail-status-control-v146 {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(150px, 190px);
  align-items: center;
  gap: 12px;
  margin: 12px 0 4px;
  padding: 10px 12px;
  border: 1px solid #d8e6ef;
  border-radius: 14px;
  background: linear-gradient(180deg, #f8fcff, #f2f8fc);
}
.detail-status-label-v146 {
  min-width: 0;
  display: grid;
  gap: 2px;
}
.detail-status-label-v146 strong {
  color: #244c69;
  font-size: .84rem;
}
.detail-status-label-v146 span {
  color: #71889a;
  font-size: .7rem;
}
.detail-status-select-v146 {
  width: 100%;
  min-height: 38px;
  border: 1px solid #cbdde8;
  border-radius: 11px;
  background: #fff;
  color: #183b55;
  padding: 0 10px;
  font: inherit;
  font-size: .82rem;
  font-weight: 900;
  cursor: pointer;
}
.detail-status-select-v146:focus-visible {
  outline: 3px solid #f3b83c;
  outline-offset: 2px;
}
.detail-status-select-v146[aria-busy="true"] {
  opacity: .65;
  cursor: wait;
}

/* The existing task form remains the source of truth for quick status saves.
   Hide it only during the short automatic submit; reveal after 2.5s on failure/slow network. */
body.v146-quick-status-saving #taskDialog[open] {
  opacity: 0 !important;
  visibility: hidden !important;
  pointer-events: none !important;
}
body.v146-quick-status-saving #taskDialog::backdrop {
  background: transparent !important;
  backdrop-filter: none !important;
}

.todo-history-v146 {
  margin-top: 2px !important;
  border-color: #d9e5ed !important;
  background: linear-gradient(180deg, rgba(249,252,254,.96), rgba(244,249,252,.82)) !important;
}
.todo-history-heading-v146 {
  align-items: center !important;
}
.todo-history-heading-v146 > div:first-child {
  min-width: 0;
  display: grid;
  gap: 2px;
}
.todo-history-heading-v146 small {
  color: #71889a;
  font-size: .68rem;
  font-weight: 800;
}
.todo-list-heading-actions-v146 {
