/* Ver.160: polish the desktop auto-collapsing sidebar and keep the task toolbar stable. */

@media (min-width: 981px) {
  /*
     The legacy layout uses a fixed sidebar and a fixed detail panel.  Ver.158
     introduced grid tracks for those fixed elements, which can win again when
     the sidebar becomes pinned.  Always keep the shell itself to one content
     track; reserve sidebar space only with margin-left.
  */
  html body.desktop-sidebar-v158 .app-shell,
  html body.desktop-sidebar-v158 .app-shell.detail-open,
  html body.desktop-sidebar-v158.desktop-sidebar-expanded .app-shell,
  html body.desktop-sidebar-v158.desktop-sidebar-expanded .app-shell.detail-open,
  html body.desktop-sidebar-v158.desktop-sidebar-pinned .app-shell,
  html body.desktop-sidebar-v158.desktop-sidebar-pinned .app-shell.detail-open {
    display: grid !important;
    grid-template-columns: minmax(0, 1fr) !important;
    width: auto !important;
    max-width: none !important;
    min-width: 0 !important;
    box-sizing: border-box !important;
  }

  html body.desktop-sidebar-v158 .app-shell,
  html body.desktop-sidebar-v158 .app-shell.detail-open,
  html body.desktop-sidebar-v158.desktop-sidebar-expanded .app-shell,
  html body.desktop-sidebar-v158.desktop-sidebar-expanded .app-shell.detail-open {
    margin-left: 68px !important;
  }

  html body.desktop-sidebar-v158.desktop-sidebar-pinned .app-shell,
  html body.desktop-sidebar-v158.desktop-sidebar-pinned .app-shell.detail-open {
    margin-left: 276px !important;
  }

  /* Keep the established fixed-detail-panel model. */
  html body.desktop-sidebar-v158 .app-shell:not(.detail-open) {
    padding-right: 0 !important;
  }

  html body.desktop-sidebar-v158 .app-shell.detail-open {
    padding-right: calc(var(--fixed-detail-width) + var(--fixed-detail-gap)) !important;
  }

  html body.desktop-sidebar-v158 .main,
  html body.desktop-sidebar-v158 .main-content {
    width: auto !important;
    min-width: 0 !important;
    max-width: none !important;
  }

  /*
     style.css has an old sidebar::after background extension.  Once the real
     sidebar shrinks to 68px that fixed pseudo element leaks over the top-left
     of the workspace.  The sidebar itself now covers the full viewport height,
     so the pseudo element is no longer needed.
  */
  html body.desktop-sidebar-v158 .sidebar::after {
    content: none !important;
    display: none !important;
  }

  /* Collapsed rail should contain only the actual navigation/brand icons. */
  html body.desktop-sidebar-v158 .desktop-sidebar-pin-v158 {
