}

.work-memo-tags-v167 {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-bottom: 12px;
}

.work-memo-tags-v167 span {
  padding: 4px 8px;
  border-radius: 999px;
  background: #f4f7fa;
  color: #607786;
  font-size: 11px;
  font-weight: 700;
}

.work-memo-meta-v167 {
  display: flex;
  justify-content: space-between;
  gap: 10px;
