  max-height: min(88vh, 860px);
  overflow: auto;
}

.work-memo-form-grid-v167 {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(180px, 240px);
  gap: 12px;
}

.work-memo-dialog-v167 textarea {
  resize: vertical;
  line-height: 1.6;
}

.work-memo-pin-row-v167 {
  margin-top: 10px;
}

.work-memo-dialog-actions-v167 {
  align-items: center;
}

.work-memo-dialog-spacer-v167 {
  flex: 1 1 auto;
}

.task-start-date-field-v167 small {
  display: block;
  margin-top: 5px;
  color: #718896;
  font-size: 11px;
  line-height: 1.45;
}

.reserved-task-button-v167 {
  align-self: center;
  white-space: nowrap;
}

.reserved-task-button-v167 span {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 24px;
  min-height: 24px;
  margin-left: 6px;
  padding: 0 7px;
  border-radius: 999px;
  background: #fff0a6;
  color: #795900;
  font-size: 12px;
  font-weight: 900;
}

.reserved-task-lead-v167 {
  margin: 0 0 16px;
  padding: 12px 14px;
  border-radius: 14px;
  background: #eef7fb;
  color: #42677c;
  line-height: 1.55;
}

.reserved-task-list-v167 {
  display: grid;
  gap: 12px;
}

.reserved-task-card-v167 {
  display: grid;
  grid-template-columns: minmax(150px, 185px) minmax(0, 1fr);
  gap: 12px 18px;
  padding: 16px;
  border: 1px solid #d8e5ec;
  border-radius: 18px;
  background: #fff;
}

.reserved-task-date-v167 {
  align-self: start;
  padding: 12px;
  border-radius: 14px;
  background: #f4f9fc;
}

.reserved-task-date-v167 small,
.reserved-task-date-v167 strong {
  display: block;
}

.reserved-task-date-v167 small {
  margin-bottom: 4px;
  color: #6c8798;
}

.reserved-task-date-v167 strong {
  color: #1f526e;
}

.reserved-task-main-v167 h3 {
  margin: 0 0 6px;
  font-size: 16px;
  color: #173d58;
}

.reserved-task-main-v167 p,
.reserved-task-main-v167 div {
  margin: 0;
  color: #587284;
  font-size: 13px;
  line-height: 1.55;
}

.reserved-task-actions-v167 {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: minmax(190px, 1fr) auto auto;
  align-items: end;
  gap: 8px;
  padding-top: 12px;
  border-top: 1px solid #edf2f5;
}

.reserved-task-actions-v167 label {
  margin: 0;
}

.task-start-detail-v167 {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 10px;
  padding: 10px 12px;
  border: 1px solid #d8e8f0;
  border-radius: 12px;
  background: #f4f9fc;
}

.task-start-detail-v167 span {
