}

@media (max-width: 860px) {
  .work-memo-view-v167 {
    padding: 10px 0 28px;
  }

  .work-memo-head-v167 {
    display: grid;
    padding: 18px;
    border-radius: 18px;
  }

  .work-memo-head-v167 .primary-button {
    width: 100%;
    min-height: 44px;
  }

  .work-memo-tools-v167 {
    grid-template-columns: 1fr;
  }

  .work-memo-count-v167 {
    justify-self: start;
  }

  .work-memo-grid-v167 {
    grid-template-columns: 1fr;
  }

  .work-memo-actions-v167 {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .work-memo-actions-v167 button {
    min-height: 44px;
  }

  .work-memo-dialog-v167,
  .reserved-task-dialog-v167 {
    width: calc(100vw - 16px);
    max-width: none;
    max-height: calc(100dvh - 16px);
    margin: 8px;
  }

  .work-memo-form-grid-v167 {
    grid-template-columns: 1fr;
  }

  .reserved-task-card-v167 {
    grid-template-columns: 1fr;
  }

  .reserved-task-actions-v167 {
    grid-template-columns: 1fr 1fr;
  }

  .reserved-task-actions-v167 label {
    grid-column: 1 / -1;
  }

  .reserved-task-actions-v167 button {
    min-height: 44px;
  }

  .reserved-task-button-v167 {
    min-height: 44px;
  }
}

ui-v168.css:
/* Ver.168: refined business memo UI, start-date alignment, and navigation icon parity. */

/* Start date: keep the helper text beside the field title so the two date inputs stay aligned. */
.task-start-date-field-v167 {
  align-content: start;
}

.task-start-date-heading-v168 {
  display: flex;
  align-items: baseline;
  gap: 10px;
  min-width: 0;
}

.task-start-date-title-v168 {
  flex: 0 0 auto;
}

.task-start-date-heading-v168 small {
  display: inline !important;
  min-width: 0;
  margin: 0 !important;
  color: #718896;
  font-size: 11px !important;
  font-weight: 700;
  line-height: 1.3 !important;
}

/* Navigation icons: make the new memo icon match the visual size/depth of the existing menu set. */
.nav-item[data-layout="todos"] .nav-icon,
.work-memo-nav-v167 .nav-icon {
  width: 42px;
  height: 42px;
  flex: 0 0 42px;
  display: grid;
  place-items: center;
}

.nav-item[data-layout="todos"] .nav-icon img,
.work-memo-nav-v167 .nav-icon img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
}

/* Memo hub: denser, easier to scan, and closer to a modern document/list hub. */
.work-memo-head-v167 {
  padding: 21px 24px;
}

.work-memo-head-v167 h3 {
  margin-top: 3px;
}

.work-memo-tools-v167 {
  grid-template-columns: minmax(280px, 1fr) minmax(180px, 230px) auto;
  gap: 10px;
  margin: 14px 0 16px;
  padding: 10px;
  border: 1px solid rgba(80, 133, 168, .15);
  border-radius: 18px;
  background: rgba(255,255,255,.76);
  box-shadow: 0 8px 24px rgba(38, 92, 125, .05);
}

.work-memo-search-v167 {
  min-height: 50px;
  padding: 0 15px;
  border-radius: 15px;
}

.work-memo-search-v167 input {
  height: 48px;
  font-size: 14px;
}

.work-memo-tools-v167 select {
  width: 100%;
  min-height: 50px;
  padding: 0 13px;
  border: 1px solid #d8e6ef;
  border-radius: 15px;
  background: #fff;
  color: #294a60;
  font: inherit;
  font-size: 14px;
  font-weight: 800;
}

.work-memo-count-v167 {
  min-height: 44px;
  padding: 0 13px;
}

.work-memo-grid-v167 {
  gap: 14px;
  align-items: start;
}

.work-memo-card-v167 {
  display: grid;
  align-content: start;
  padding: 16px;
  border-radius: 18px;
  box-shadow: 0 7px 20px rgba(45, 92, 120, .055);
  transition: transform .14s ease, box-shadow .14s ease, border-color .14s ease;
}

.work-memo-card-v167:hover {
  transform: translateY(-1px);
  box-shadow: 0 12px 28px rgba(45, 92, 120, .09);
}

.work-memo-card-v167.is-pinned {
  border-color: #efc54f;
  box-shadow: 0 8px 24px rgba(218, 167, 34, .10);
}

.work-memo-card-head-v167 {
  gap: 14px;
}

.work-memo-card-head-v167 h4 {
  margin: 7px 0 0;
  font-size: 18px;
  line-height: 1.4;
}

.work-memo-category-v167 {
  min-height: 25px;
  padding: 0 9px;
  font-size: 11px;
}

/* "Fixed" is an operational state, not a favourite. Use explicit text instead of a star. */
.work-memo-pin-v167 {
  width: auto;
  min-width: 58px;
  height: 34px;
  padding: 0 11px;
  border-radius: 999px;
  color: #48677a;
  font-size: 12px;
  font-weight: 900;
  line-height: 1;
  white-space: nowrap;
}

.work-memo-pin-v167:hover {
  background: #f4f9fc;
  border-color: #c8dae5;
}

.work-memo-pin-v167.active,
.work-memo-pin-v167[aria-pressed="true"] {
  min-width: 76px;
  background: #fff5c7;
  border-color: #efc54f;
  color: #7c5b00;
}

.work-memo-body-v167 {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 5;
  margin: 13px 0 10px;
  min-height: 0;
  max-height: none;
  padding: 11px 12px;
  overflow: hidden;
  border: 1px solid #edf2f5;
  border-radius: 13px;
  background: #f8fbfd;
  font-size: 13.5px;
  line-height: 1.65;
}

.work-memo-tags-v167 {
  margin: 0 0 10px;
}

.work-memo-meta-v167 {
  padding-top: 10px;
}

.work-memo-actions-v167 {
  gap: 7px;
  margin-top: 10px;
}

.work-memo-actions-v167 button {
  min-height: 40px;
  border-radius: 13px;
}

/* Memo editor: make pinning a clearly labelled, large click target. */
.work-memo-pin-row-v167 {
  display: flex !important;
  grid-template-columns: none !important;
  align-items: flex-start !important;
  justify-content: flex-start !important;
  gap: 12px !important;
  margin-top: 14px !important;
  padding: 13px 15px;
  border: 1px solid #d8e6ef;
  border-radius: 15px;
  background: #f7fbfd;
  color: #34566d !important;
  cursor: pointer;
}

.work-memo-pin-row-v167:hover {
  border-color: #b9d5e4;
  background: #f1f9fc;
}

.work-memo-pin-row-v167 input {
  width: 22px !important;
  height: 22px !important;
  flex: 0 0 22px;
  margin: 1px 0 0 !important;
  padding: 0 !important;
  accent-color: #299bb8;
  cursor: pointer;
}

.work-memo-pin-copy-v168 {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.work-memo-pin-copy-v168 strong {
  color: #274d65;
  font-size: 14px;
  line-height: 1.35;
}

.work-memo-pin-copy-v168 small {
  color: #718896;
  font-size: 11px;
  font-weight: 700;
  line-height: 1.45;
}

@media (max-width: 1240px) {
  .work-memo-tools-v167 {
    grid-template-columns: minmax(220px, 1fr) minmax(160px, 210px) auto;
  }
}

@media (max-width: 860px) {
  .task-start-date-heading-v168 {
    flex-wrap: wrap;
    gap: 3px 8px;
  }

  .task-start-date-heading-v168 small {
    flex-basis: 100%;
  }

  .work-memo-head-v167 {
    padding: 17px;
  }

  .work-memo-tools-v167 {
    grid-template-columns: 1fr;
    padding: 8px;
    border-radius: 16px;
  }

  .work-memo-search-v167,
  .work-memo-tools-v167 select {
    min-height: 50px;
  }

  .work-memo-count-v167 {
    min-height: 36px;
  }

  .work-memo-card-v167 {
    padding: 15px;
  }

  .work-memo-body-v167 {
    -webkit-line-clamp: 7;
  }

  .work-memo-pin-v167 {
    min-height: 38px;
  }

  .work-memo-actions-v167 button {
    min-height: 44px;
  }
}

/* Ver.188 ownership: retain the compact memo tool row formerly applied by ui-v176.css. */
body.work-memo-mode-v167 .work-memo-tools-v167 {
  display: flex !important;
  align-items: center !important;
  gap: 12px !important;
  min-width: 0;
}
body.work-memo-mode-v167 .work-memo-new-v176 {
  order: -2;
  flex: 0 0 auto;
  min-height: 48px;
  white-space: nowrap;
}
body.work-memo-mode-v167 .work-memo-search-v167 {
  flex: 1 1 620px !important;
  min-width: 240px;
}
body.work-memo-mode-v167 .work-memo-tools-v167 > select {
  flex: 0 0 min(260px, 22vw);
  min-height: 48px;
}
body.work-memo-mode-v167 .work-memo-count-v167 {
  flex: 0 0 auto;
  white-space: nowrap;
}

@media (max-width: 980px) {
  body.work-memo-mode-v167 .work-memo-tools-v167 {
    flex-wrap: wrap;
  }
  body.work-memo-mode-v167 .work-memo-search-v167 {
    flex-basis: calc(100% - 150px) !important;
  }
}

@media (max-width: 860px) {
  body.work-memo-mode-v167 .work-memo-search-v167 {
    flex: 1 1 100% !important;
  }
  body.work-memo-mode-v167 .work-memo-new-v176 {
    flex: 0 0 auto;
  }
  body.work-memo-mode-v167 .work-memo-tools-v167 > select {
    flex: 1 1 220px;
  }
}

ui-v176.css:
/* Ver.176: compact duplicated headings so primary work content stays above the fold. */

/* Today: action buttons now share the announcement header instead of consuming a second card. */
body.today-mode .activity-panel .activity-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 10px;
}
body.today-mode .activity-panel .today-compact-action-v176 {
  min-height: 44px;
  white-space: nowrap;
}

/* ToDo: search, result count and the two navigation actions share one compact row. */
body.todo-mode .todo-tools-v145 {
  display: flex !important;
  align-items: center !important;
  gap: 12px !important;
  min-width: 0;
}
body.todo-mode .todo-tools-v145 .todo-search-box-v145 {
  flex: 1 1 520px;
  min-width: 220px;
}
body.todo-mode .todo-tools-v145 .todo-search-result-v145 {
  flex: 0 0 auto;
  white-space: nowrap;
}
body.todo-mode .todo-tools-actions-v176 {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-left: auto;
  flex: 0 0 auto;
}
body.todo-mode .todo-tools-actions-v176 > button {
  min-height: 44px;
  white-space: nowrap;
}

/* Schedule: the old standalone search row is replaced by one integrated control bar. */
body.schedule-mode .toolbar {
  display: none !important;
}
body.schedule-mode .schedule-head {
  display: block !important;
  padding: 18px 20px !important;
}
body.schedule-mode .schedule-toolbar-v176 {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 18px;
  min-width: 0;
}
body.schedule-mode .schedule-toolbar-controls-v176 {
  display: flex;
  align-items: flex-end;
  gap: 14px;
  min-width: 0;
  flex: 0 1 auto;
}
body.schedule-mode .schedule-toolbar-controls-v176 > .schedule-new-button {
  order: 0;
  min-height: 46px;
  white-space: nowrap;
}
body.schedule-mode .schedule-toolbar-controls-v176 .schedule-control-group {
  margin: 0 !important;
}
body.schedule-mode .schedule-toolbar-controls-v176 .schedule-control-group > span {
  display: block;
  margin-bottom: 6px;
}
body.schedule-mode .schedule-toolbar-utility-v176 {
  display: flex;
  align-items: flex-end;
  justify-content: flex-end;
  gap: 12px;
  min-width: 300px;
  flex: 1 1 520px;
}
body.schedule-mode .schedule-date-v176 {
  display: inline-flex;
  align-items: center;
  min-height: 46px;
  padding: 0 14px;
  border: 1px solid #cfe0ec;
  border-radius: 15px;
  background: #f4f9fc;
  color: #345b79;
  font-weight: 800;
  white-space: nowrap;
}
body.schedule-mode .schedule-date-v176 .schedule-range-label {
  margin: 0 !important;
  white-space: nowrap;
}
body.schedule-mode .schedule-search-v176 {
  display: flex;
  align-items: center;
  gap: 9px;
  min-height: 46px;
  padding: 0 14px;
  border: 1px solid #cfe0ec;
  border-radius: 15px;
  background: #fff;
  flex: 1 1 360px;
  min-width: 220px;
}
body.schedule-mode .schedule-search-v176 input {
  width: 100%;
  min-width: 0;
  border: 0 !important;
  outline: 0 !important;
  box-shadow: none !important;
  background: transparent !important;
  padding: 0 !important;
}

/* Business memo: new-memo action starts the search/filter row; the duplicate intro card is removed. */
body.work-memo-mode-v167 .work-memo-tools-v167 {
  display: flex !important;
  align-items: center !important;
  gap: 12px !important;
  min-width: 0;
}
body.work-memo-mode-v167 .work-memo-new-v176 {
  order: -2;
  flex: 0 0 auto;
  min-height: 48px;
  white-space: nowrap;
}
body.work-memo-mode-v167 .work-memo-search-v167 {
  flex: 1 1 620px !important;
  min-width: 240px;
}
body.work-memo-mode-v167 .work-memo-tools-v167 > select {
  flex: 0 0 min(260px, 22vw);
  min-height: 48px;
}
body.work-memo-mode-v167 .work-memo-count-v167 {
  flex: 0 0 auto;
  white-space: nowrap;
}

@media (max-width: 1380px) {
  body.schedule-mode .schedule-toolbar-v176 {
    align-items: stretch;
    flex-wrap: wrap;
  }
  body.schedule-mode .schedule-toolbar-controls-v176,
  body.schedule-mode .schedule-toolbar-utility-v176 {
    flex: 1 1 100%;
  }
  body.schedule-mode .schedule-toolbar-utility-v176 {
    min-width: 0;
  }
}

@media (max-width: 980px) {
  body.todo-mode .todo-tools-v145,
  body.work-memo-mode-v167 .work-memo-tools-v167 {
    flex-wrap: wrap;
  }
  body.todo-mode .todo-tools-actions-v176 {
    margin-left: 0;
  }
  body.schedule-mode .schedule-toolbar-controls-v176 {
    flex-wrap: wrap;
  }
  body.work-memo-mode-v167 .work-memo-search-v167 {
    flex-basis: calc(100% - 150px) !important;
  }
}

@media (max-width: 860px) {
  body.today-mode .activity-panel .activity-actions {
    justify-content: flex-start;
  }
  body.todo-mode .todo-tools-v145 .todo-search-box-v145,
  body.todo-mode .todo-tools-actions-v176,
  body.work-memo-mode-v167 .work-memo-search-v167 {
    flex: 1 1 100% !important;
  }
  body.todo-mode .todo-tools-actions-v176 {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    width: 100%;
  }
  body.schedule-mode .schedule-toolbar-controls-v176,
  body.schedule-mode .schedule-toolbar-utility-v176 {
    display: flex;
    flex-wrap: wrap;
    align-items: stretch;
  }
  body.schedule-mode .schedule-toolbar-controls-v176 > *,
  body.schedule-mode .schedule-date-v176,
  body.schedule-mode .schedule-search-v176 {
    flex: 1 1 100%;
  }
  body.work-memo-mode-v167 .work-memo-new-v176 {
    flex: 0 0 auto;
  }
  body.work-memo-mode-v167 .work-memo-tools-v167 > select {
    flex: 1 1 220px;
  }
}
